import json
import os
import tempfile
import unittest

from shipcalc import cache, cli, export, format as fmt, limits, reports, storage, units, validate
from shipcalc.calc import order_weight_kg, quote
from shipcalc.models import Item, Order
from shipcalc.packing import split_parcels
from shipcalc.units import WeightError


class UnitsTest(unittest.TestCase):
    def test_normalize_pads_and_rounds_half_to_even(self):
        self.assertEqual(units.normalize_kg("2"), "2.000")
        self.assertEqual(units.normalize_kg("0.250"), "0.250")
        self.assertEqual(units.normalize_kg("1.0005"), "1.000")
        self.assertEqual(units.normalize_kg("1.0015"), "1.002")
        self.assertEqual(units.normalize_kg("2.0025"), "2.002")
        self.assertEqual(units.normalize_kg("0.0004"), "0.000")

    def test_normalize_accepts_long_input(self):
        self.assertEqual(units.normalize_kg("1" * 40 + ".5"), "1" * 40 + ".500")

    def test_invalid_input_raises_weight_error_with_message(self):
        bad = ["-1", "+1", "1e3", "nan", "inf", "", " 1", "1 ", "1,5", "1.", ".5", ".", "1_000"]
        for value in bad:
            with self.subTest(value=value), self.assertRaises(WeightError) as ctx:
                units.normalize_kg(value)
            self.assertEqual(str(ctx.exception), f"invalid weight: {value!r}")
        for value in [1, 1.5, True, None]:
            with self.subTest(value=value), self.assertRaises(WeightError):
                units.normalize_kg(value)

    def test_weight_error_is_value_error(self):
        self.assertTrue(issubclass(WeightError, ValueError))

    def test_trailing_newline_is_invalid(self):
        with self.assertRaises(WeightError):
            units.normalize_kg("1.5\n")

    def test_kg_to_g_and_g_to_kg(self):
        self.assertEqual(units.kg_to_g("1.25"), 1250)
        self.assertEqual(units.kg_to_g("0.000"), 0)
        self.assertEqual(units.g_to_kg(1250), "1.250")
        self.assertEqual(units.g_to_kg(5), "0.005")
        self.assertEqual(units.g_to_kg(0), "0.000")
        for bad in [-1, True, 1.5, "1", None]:
            with self.subTest(value=bad), self.assertRaises(WeightError):
                units.g_to_kg(bad)


class ModelsTest(unittest.TestCase):
    def test_weight_is_normalised(self):
        self.assertEqual(Item("A", "1000").weight_kg, "1000.000")

    def test_line_weight_is_canonical(self):
        self.assertEqual(Item("A", "0.5", 3).line_weight_kg(), "1.500")


class CalcTest(unittest.TestCase):
    def test_carrier_limit_boundary(self):
        self.assertEqual(limits.check_total_kg("2147483.647"), "2147483.647")
        with self.assertRaises(WeightError):
            limits.check_total_kg("2147483.648")
        order = Order([Item("A", "2147483.647"), Item("B", "0.001")])
        with self.assertRaises(WeightError):
            order_weight_kg(order)

    def test_quote_has_weight_kg_and_is_otherwise_unchanged(self):
        result = quote(Order([Item("A", "0.5")]), "eu")
        self.assertEqual(set(result), {"parcels", "weight_kg", "cents"})
        self.assertEqual(result["weight_kg"], "0.500")


class PackingTest(unittest.TestCase):
    def test_parcels_store_canonical_kg(self):
        parcels = split_parcels(Order([Item("A", "12.000"), Item("B", "9.000")]))
        self.assertEqual([p.weight_kg for p in parcels], ["12.000", "9.000"])

    def test_unit_exactly_at_limit_fits(self):
        parcels = split_parcels(Order([Item("A", "20.000"), Item("B", "0.001")]))
        self.assertEqual(len(parcels), 2)

    def test_unit_over_limit_travels_alone(self):
        parcels = split_parcels(Order([Item("A", "25.000")]))
        self.assertEqual([p.weight_kg for p in parcels], ["25.000"])


class ReportsTest(unittest.TestCase):
    def test_average_rounds_half_to_even(self):
        # total 0.003 kg over 2 units: 1.5 g, ties to even -> 2 g
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "0.001"), Item("B", "0.002")])), "0.002")
        # total 0.001 kg over 2 units: 0.5 g, ties to even -> 0 g
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "0.001", 2)])), "0.000")

    def test_average_of_empty_order(self):
        self.assertEqual(reports.average_weight_kg(Order()), "0.000")

    def test_average_not_integer_division(self):
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "0.001"), Item("B", "0.002")])), "0.002")
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "1.000"), Item("B", "0.002")])), "0.501")

    def test_heaviest_is_numeric_and_ties_by_sku(self):
        order = Order([Item("B", "9.000"), Item("A", "10.000"), Item("C", "9.000"), Item("D", "0.500")])
        self.assertEqual([i.sku for i in reports.heaviest(order)], ["A", "B", "C"])

    def test_weight_bands_thresholds(self):
        order = Order([
            Item("L", "0.500", 1), Item("M", "0.501", 2), Item("M2", "2.000", 1), Item("H", "2.001", 3),
        ])
        self.assertEqual(reports.weight_bands(order), {"light": 1, "medium": 3, "heavy": 3})


class FormatTest(unittest.TestCase):
    def test_format_weight(self):
        self.assertEqual(fmt.format_weight("0.250"), "0.250 kg")
        self.assertEqual(fmt.format_weight("12.000"), "12.000 kg")

    def test_format_table_layout(self):
        table = fmt.format_table(Order([Item("MUG-01", "0.350", 2)]))
        self.assertEqual(table, "MUG-01         0.350 kg  x2")


class ExportTest(unittest.TestCase):
    def test_csv_stays_in_grams_as_integers(self):
        order = Order([Item("MUG-01", "0.350", 2), Item("BOOK-07", "1.200")])
        self.assertEqual(export.to_csv(order), "sku,weight_g,qty\nMUG-01,350,2\nBOOK-07,1200,1\n")

    def test_carrier_payload_is_int_grams(self):
        payload = export.carrier_payload(Order([Item("A", "1.250", 2)]))
        self.assertEqual(payload, {"weight_g": 2500, "parcels": 1})
        self.assertIs(type(payload["weight_g"]), int)


class CacheTest(unittest.TestCase):
    def test_quote_key_is_v2_kg(self):
        order = Order([Item("A", "1.5"), Item("B", "2")])
        self.assertEqual(cache.quote_key(order, "eu"), "quote:v2:eu:3.500:2")


class StorageTest(unittest.TestCase):
    def setUp(self):
        self._dir = tempfile.TemporaryDirectory()
        self.path = os.path.join(self._dir.name, "order.json")

    def tearDown(self):
        self._dir.cleanup()

    def _write(self, data):
        with open(self.path, "w", encoding="utf-8") as handle:
            json.dump(data, handle)

    def test_schema1_loads_grams_exactly(self):
        self._write({"schema": 1, "items": [{"sku": "A", "weight_g": 1250, "qty": 2}]})
        order = storage.load(self.path)
        self.assertEqual(order.items[0].weight_kg, "1.250")
        self.assertEqual(order.items[0].qty, 2)

    def test_schema1_invalid_grams_raise(self):
        for bad in [-5, "350", True, 1.5]:
            with self.subTest(value=bad):
                self._write({"schema": 1, "items": [{"sku": "A", "weight_g": bad}]})
                with self.assertRaises(WeightError):
                    storage.load(self.path)

    def test_schema2_is_normalised_on_load(self):
        self._write({"schema": 2, "items": [{"sku": "A", "weight_kg": "1.5", "qty": 1}]})
        self.assertEqual(storage.load(self.path).items[0].weight_kg, "1.500")

    def test_schema2_invalid_weight_raises(self):
        self._write({"schema": 2, "items": [{"sku": "A", "weight_kg": "1,5", "qty": 1}]})
        with self.assertRaises(WeightError):
            storage.load(self.path)

    def test_unknown_schema_raises_value_error(self):
        for bad in [3, True, "2", None]:
            with self.subTest(schema=bad):
                self._write({"schema": bad, "items": []})
                with self.assertRaises(ValueError):
                    storage.load(self.path)

    def test_save_writes_schema2(self):
        storage.save(Order([Item("A", "0.250")]), self.path)
        with open(self.path, encoding="utf-8") as handle:
            data = json.load(handle)
        self.assertEqual(data["schema"], 2)
        self.assertEqual(data["items"], [{"sku": "A", "weight_kg": "0.250", "qty": 1}])


class ValidateTest(unittest.TestCase):
    def _item(self, weight):
        return {"sku": "A", "weight_kg": weight, "qty": 1}

    def test_weight_range_applies_after_rounding(self):
        self.assertIn("weight_kg: out of range 0.001..1000.000", validate.validate_item(self._item("0.0004")))
        self.assertEqual(validate.validate_item(self._item("1000.0004")), [])
        self.assertEqual(validate.validate_item(self._item("0.001")), [])

    def test_invalid_weight_is_a_problem(self):
        problems = validate.validate_item(self._item("1,5"))
        self.assertEqual(problems, ["weight_kg: invalid weight: '1,5'"])

    def test_weight_g_only_is_missing_weight_kg(self):
        problems = validate.validate_item({"sku": "A", "weight_g": 1, "qty": 1})
        self.assertIn("weight_kg: missing", problems)


class CliTest(unittest.TestCase):
    def setUp(self):
        self._dir = tempfile.TemporaryDirectory()
        self.path = os.path.join(self._dir.name, "order.json")

    def tearDown(self):
        self._dir.cleanup()

    def test_add_rejects_invalid_weight_with_status_2(self):
        storage.save(Order(), self.path)
        import io
        import contextlib
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            status = cli.main(["add", self.path, "A", "1,5", "1"])
        self.assertEqual(status, 2)
        self.assertEqual(err.getvalue(), "error: invalid weight: '1,5'\n")

    def test_add_then_quote_in_kg(self):
        storage.save(Order(), self.path)
        import io
        import contextlib
        self.assertEqual(cli.main(["add", self.path, "A", "0.350", "2"]), 0)
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            self.assertEqual(cli.main(["quote", self.path, "--zone", "eu"]), 0)
        self.assertIn("total weight: 0.700 kg", out.getvalue())


if __name__ == "__main__":
    unittest.main()

